/**
 * A byte-exact port of CPython's random.Random (Mersenne Twister + the
 * derived samplers used by nomo_planner.serving_sim). It exists so the
 * browser serving simulator reproduces the Python reference simulator
 * request-for-request with the same seed — the parity goldens in
 * scripts/serving-sim-golden.json are generated by Python and checked here.
 *
 * References: CPython Lib/random.py and Modules/_randommodule.c (3.12).
 */

const N = 624;
const M = 397;
const MATRIX_A = 0x9908b0df;
const UPPER_MASK = 0x80000000;
const LOWER_MASK = 0x7fffffff;

const LOG4 = Math.log(4.0);
const SG_MAGICCONST = 1.0 + Math.log(4.5);
// CPython 3.11+ random.py: NV_MAGICCONST = 4 * exp(-0.5) / sqrt(2.0)
const NV_MAGICCONST = 4 * Math.exp(-0.5) / Math.sqrt(2.0);

function imul(a: number, b: number): number {
  return Math.imul(a, b) >>> 0;
}

export class PyRandom {
  private mt = new Uint32Array(N);
  private mti = N + 1; // N+1 means the state is not initialized yet
  private gaussNext: number | null = null;

  constructor(seed = 0) {
    this.seedInt(seed);
  }

  /** CPython random_seed: abs int -> little-endian 32-bit words -> init_by_array. */
  seedInt(seed: number): void {
    let value = Math.abs(Math.trunc(seed));
    if (!Number.isFinite(value)) value = 0;
    const words: number[] = [];
    if (value === 0) {
      words.push(0);
    } else {
      let rest = value;
      while (rest > 0) {
        words.push(rest % 4294967296);
        rest = Math.floor(rest / 4294967296);
      }
    }
    this.initByArray(words);
  }

  private initGenrand(s: number): void {
    const mt = this.mt;
    mt[0] = s >>> 0;
    for (let i = 1; i < N; i++) {
      mt[i] = (imul(1812433253, mt[i - 1]! ^ (mt[i - 1]! >>> 30)) + i) >>> 0;
    }
    this.mti = N;
    this.gaussNext = null;
  }

  private initByArray(initKey: number[]): void {
    this.initGenrand(19650218);
    const mt = this.mt;
    let i = 1;
    let j = 0;
    for (let k = Math.max(N, initKey.length); k > 0; k--) {
      mt[i] = ((mt[i]! ^ imul(mt[i - 1]! ^ (mt[i - 1]! >>> 30), 1664525)) + (initKey[j]! >>> 0) + j) >>> 0;
      i++;
      j++;
      if (i >= N) {
        mt[0] = mt[N - 1]!;
        i = 1;
      }
      if (j >= initKey.length) j = 0;
    }
    for (let k = N - 1; k > 0; k--) {
      mt[i] = ((mt[i]! ^ imul(mt[i - 1]! ^ (mt[i - 1]! >>> 30), 1566083941)) - i) >>> 0;
      i++;
      if (i >= N) {
        mt[0] = mt[N - 1]!;
        i = 1;
      }
    }
    mt[0] = UPPER_MASK;
    this.gaussNext = null;
  }

  genrandInt32(): number {
    const mt = this.mt;
    let y: number;
    if (this.mti >= N) {
      if (this.mti === N + 1) this.initGenrand(5489);
      let kk = 0;
      for (; kk < N - M; kk++) {
        y = (mt[kk]! & UPPER_MASK) | (mt[kk + 1]! & LOWER_MASK);
        mt[kk] = mt[kk + M]! ^ (y >>> 1) ^ (y & 1 ? MATRIX_A : 0);
      }
      for (; kk < N - 1; kk++) {
        y = (mt[kk]! & UPPER_MASK) | (mt[kk + 1]! & LOWER_MASK);
        mt[kk] = mt[kk + (M - N)]! ^ (y >>> 1) ^ (y & 1 ? MATRIX_A : 0);
      }
      y = (mt[N - 1]! & UPPER_MASK) | (mt[0]! & LOWER_MASK);
      mt[N - 1] = mt[M - 1]! ^ (y >>> 1) ^ (y & 1 ? MATRIX_A : 0);
      this.mti = 0;
    }
    y = mt[this.mti++]!;
    y ^= y >>> 11;
    y = (y ^ ((y << 7) & 0x9d2c5680)) >>> 0;
    y = (y ^ ((y << 15) & 0xefc60000)) >>> 0;
    y ^= y >>> 18;
    return y >>> 0;
  }

  /** CPython random(): genrand_res53. */
  random(): number {
    const a = this.genrandInt32() >>> 5;
    const b = this.genrandInt32() >>> 6;
    return (a * 67108864 + b) * (1 / 9007199254740992);
  }

  getrandbits(k: number): number {
    if (k <= 0) return 0;
    if (k <= 32) return this.genrandInt32() >>> (32 - k);
    // k > 32: CPython assembles big-int words most-significant first.
    let acc = 0;
    let bits = k;
    const parts: number[] = [];
    while (bits > 0) {
      const take = bits >= 32 ? 32 : bits;
      parts.push(this.genrandInt32() >>> (32 - take));
      bits -= 32;
    }
    for (let i = parts.length - 1; i >= 0; i--) {
      acc = acc * 4294967296 + parts[i]!;
    }
    return acc;
  }

  /** CPython _randbelow_with_getrandbits. */
  private randbelow(n: number): number {
    if (n <= 0) return 0;
    const bitLength = Math.floor(Math.log2(n)) + 1; // == n.bit_length() for n >= 1
    let r = this.getrandbits(bitLength);
    while (r >= n) r = this.getrandbits(bitLength);
    return r;
  }

  choice<T>(seq: readonly T[]): T {
    return seq[this.randbelow(seq.length)]!;
  }

  uniform(a: number, b: number): number {
    return a + (b - a) * this.random();
  }

  /** CPython gauss: Box-Muller with a cached second draw. */
  gauss(mu = 0.0, sigma = 1.0): number {
    let z = this.gaussNext;
    this.gaussNext = null;
    if (z === null || !Number.isFinite(z)) {
      const x2pi = this.random() * Math.PI * 2;
      const g2rad = Math.sqrt(-2 * Math.log(1 - this.random()));
      z = Math.cos(x2pi) * g2rad;
      this.gaussNext = Math.sin(x2pi) * g2rad;
    }
    return mu + z * sigma;
  }

  /** CPython normalvariate: Kinderman-Monahan ratio-of-uniforms, no cache. */
  normalvariate(mu = 0.0, sigma = 1.0): number {
    for (;;) {
      const u1 = this.random();
      const u2 = 1.0 - this.random();
      const z = (NV_MAGICCONST * (u1 - 0.5)) / u2;
      const zz = (z * z) / 4.0;
      if (zz <= -Math.log(u2)) return mu + z * sigma;
    }
  }

  lognormvariate(mu: number, sigma: number): number {
    return Math.exp(this.normalvariate(mu, sigma));
  }

  expovariate(lambd: number): number {
    return -Math.log(1 - this.random()) / lambd;
  }

  /** CPython gammavariate: Cheng (alpha>1), exponential (alpha==1), Kennedy-Gentle GS (alpha<1). */
  gammavariate(alpha: number, beta: number): number {
    if (alpha <= 0 || beta <= 0) throw new Error("gammavariate: alpha and beta must be > 0.0");
    if (alpha > 1.0) {
      const ainv = Math.sqrt(2 * alpha - 1);
      const bbb = alpha - LOG4;
      const ccc = alpha + ainv;
      for (;;) {
        const u1 = this.random();
        if (!(1e-7 < u1 && u1 < 0.9999999)) continue;
        const u2 = 1.0 - this.random();
        const v = Math.log(u1 / (1.0 - u1)) / ainv;
        const x = alpha * Math.exp(v);
        const z = u1 * u1 * u2;
        const r = bbb + ccc * v - x;
        if (r + SG_MAGICCONST - 4.5 * z >= 0 || r >= Math.log(z)) return x * beta;
      }
    } else if (alpha === 1.0) {
      return -Math.log(1.0 - this.random()) * beta;
    } else {
      for (;;) {
        const u = this.random();
        const b = (Math.E + alpha) / Math.E;
        const p = b * u;
        let x: number;
        if (p <= 1.0) x = Math.pow(p, 1 / alpha);
        else x = -Math.log((b - p) / alpha);
        const u1 = this.random();
        if (p > 1.0) {
          if (u1 <= Math.pow(x, alpha - 1)) return x * beta;
        } else if (u1 <= Math.exp(-x)) return x * beta;
      }
    }
  }
}

/** serving_sim._sample_poisson: product loop at or below 40, cached-gauss normal approximation above. */
export function samplePoisson(rng: PyRandom, lam: number): number {
  if (lam <= 0) return 0;
  if (lam > 40) return Math.max(0, Math.round(rng.gauss(lam, Math.sqrt(lam))));
  const threshold = Math.exp(-lam);
  let product = 1.0;
  let count = 0;
  while (product > threshold) {
    count += 1;
    product *= rng.random();
  }
  return count - 1;
}
